import hashlib,json,copy
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path.cwd();OWN=Path(__file__).resolve().parent
def pair(de,en):return {'de':de,'en':en}
def case(key,title,material,task,response,transfer,answer,rubric):
    return dict(caseId=key,title=title,material=material,task=task,workedResponse=response,freshTransfer=transfer,freshTransferWorkedResponse=answer,rubric=rubric,materialOrigin='SkillPilot-authored fictitious didactic model; all quantities, institutional roles and source cards are constructed, not external empirical findings',license='CC-BY-4.0',actualLearnerPerformance=False,actualExperimentPerformed=False)
SPECS=[]
def goal(archetype,expectations,cases,limits):
    assert len(cases)==2 and len(expectations)>=3
    SPECS.append(dict(archetype=archetype,expectations=expectations,cases=cases,limits=limits))

# Each expectation supplies an understanding/observable-performance pair in both languages.
goal('procedure',[
 (pair('Eine konkrete biologische Frage steuert Begriffe, Suchweg und Auswahl in beiden Medienarten.','A concrete biological question guides terms, search route and selection in both media types.'),pair('Formuliere Suchbegriffe und protokolliere mindestens einen nachvollziehbaren analogen und einen digitalen Such-/Nachschlageweg.','Formulate search terms and record at least one traceable analog and one digital search/lookup route.')),
 (pair('Passende Quellen beantworten die Frage mit ihrem tatsächlichen Inhalt; Titel oder Trefferposition allein reichen nicht.','Suitable sources answer the question through their actual content; titles or search rank alone are insufficient.'),pair('Wähle begründet einschlägige Quellen, lokalisiere die verwendeten Passagen und verwerfe mindestens einen unpassenden Treffer.','Select relevant sources with reasons, locate the used passages and reject at least one unsuitable result.')),
 (pair('Text, Tabelle und komplexere Prozess-/Beziehungsdarstellung werden fragebezogen erschlossen, ohne mehr auszusagen als das Material trägt.','Text, table and more complex process/relationship representation are interpreted for the question without exceeding their evidence.'),pair('Entnimm den unterschiedlichen Darstellungen die gesuchten Informationen, verknüpfe sie und benenne einen offenen Informationsbedarf.','Extract the requested information from different representations, connect it and identify one remaining information need.'))], [
 case('research-urban-tree','Bäume und Bestäuber',pair('Gedruckter Modellkatalog: A1 Stadtbäume, Kapitel2: Blüten liefern Pollen/Nektar, Kapitel5: Arten werden saisonal besucht. A2 Holzbau, Kapitel3: Tragfähigkeit. Digitaler Modellindex: D1 Stadtlabor, kontrollierte Beobachtung von12 Baumflächen, Tabelle: Blühflächen mit40 Besuchen/Stunde, nichtblühende mit8; keine zufällige Zuteilung. D2 Blütennetz: Baumblüte → Nahrung; angrenzende Wiese → weitere Nahrung; Wetter → Aktivität. D3 Anzeige: Unser Baum garantiert fünfmal mehr Arten, ohne Artenzählung. Alle Einträge sind ausdrücklich eigenes Modellmaterial.','Printed model catalog: A1 Urban Trees, chapter2: flowers supply pollen/nectar; chapter5: species visit seasonally. A2 Timber Construction, chapter3: load bearing. Digital model index: D1 City Laboratory, observations of12 tree plots, table: flowering plots40 visits/hour, nonflowering8; no random assignment. D2 Flower Network: tree flowers → food; adjacent meadow → additional food; weather → activity. D3 Advert: Our tree guarantees five times more species, without species counts. All entries are explicitly authored model material.'),pair('Recherchiere: Welche Beiträge können blühende Stadtbäume zur Nahrung von Bestäubern leisten? Benutze den druckbaren Katalog und den durchsuchbaren digitalen Index. Notiere Suchbegriffe, analoge Kapitelwahl, digitale Treffer-/Passagenwahl und Ausschlüsse; erschließe Tabelle und Beziehungsnetz.','Research: What contributions can flowering urban trees make to pollinator food? Use the printable catalog and searchable digital index. Record terms, analog chapter choice, digital result/passage choice and exclusions; interpret table and relationship network.'),pair('Suchbegriffe Stadtbaum Blüte Pollen Bestäuber und flowering urban trees pollinator food passen. Analog A1Kap2 liefert die Nahrungsgrundlage; Kap5 begrenzt sie saisonal. Digital D1/D2 liefern Beobachtungen und konkurrierende Einflüsse. Im Modell stehen40 versus8 Besuche/Stunde; das ist weder eine Artzahl noch ein kausaler Fünffacheffekt. A2 ist fachlich unpassend; D3 beantwortet die Frage ohne überprüfbare Arten-/Ursachenevidenz. Offen bleiben Pflanzenarten, Erhebungszeit und Beiträge anderer Flächen.','Terms urban tree flower pollen pollinator and flowering urban trees pollinator food fit. Analog A1chapter2 supplies the food basis; chapter5 limits it seasonally. Digital D1/D2 provide observations and competing influences. The model shows40 versus8 visits/hour; neither is a species count or a causal fivefold effect. A2 is irrelevant; D3 lacks verifiable species/causal evidence. Plant species, sampling time and contributions of other plots remain unknown.'),pair('Ein neuer digitaler Treffer untersucht Windbestäubung bei einer Baumart ohne Nektar. Kann er die ursprüngliche Frage vollständig beantworten? Passe Such-/Quellenwahl an.','A new digital result studies wind pollination in a tree without nectar. Can it fully answer the original question? Adapt search/source choice.'),pair('Nein; er grenzt Baumarten ab, beantwortet aber nicht allein Nahrung für tierische Bestäuber. Ich ergänze Tierbestäubung und Nektar/Pollenangebote und behalte das passende analoge Kapitel.','No; it distinguishes tree types but does not alone answer food for animal pollinators. I add animal pollination and nectar/pollen supply while retaining the relevant analog chapter.'),[pair('Konkrete Frage und tatsächlich ausführbare analoge/digitale Suchpfade mit Lokatoren.','Concrete question and executable analog/digital search routes with locators.'),pair('Fragebezogene Auswahl und begründeter Ausschluss.','Question-driven selection and justified exclusion.'),pair('Tabelle und Beziehungsnetz korrekt erschlossen; Grenzen und frische Suchanpassung.','Correct interpretation of table/network; limits and fresh search adaptation.')]),
 case('research-seed-germination','Keimung und Wasserversorgung',pair('Gedrucktes Modellhandbuch B1, Register Keimung, Seiten4–5: Samen nehmen Wasser auf; bei überflutetem luftarmem Substrat ist Sauerstoffversorgung begrenzt. B2, Register Düngung, Seite9: Mineraldünger ist keine Lichtquelle. Digitaler Modellindex E1 enthält Keimzahlen bei gleicher Temperatur: mäßigfeucht18/20, trocken2/20, ständigüberflutet5/20. E2 zeigt als Ablauf: Wasseraufnahme → Stoffwechsel; Sauerstoffzufuhr → aerobe Energiebereitstellung; beide beeinflussen Keimung. E3 Blogtitel Alle Pflanzen brauchen zum Keimen Sonne, ohne Versuch oder Artangabe.','Printed model handbook B1, germination index, pages4–5: seeds take up water; oxygen supply is limited in flooded air-poor substrate. B2, fertilization index, page9: mineral fertilizer is not a light source. Digital model index E1 gives germination counts at equal temperature: moderatelymoist18/20, dry2/20, continuouslyflooded5/20. E2 flow: water uptake → metabolism; oxygen supply → aerobic energy provision; both influence germination. E3 blogtitle All plants need sunlight to germinate, without experiment or species.'),pair('Recherchiere, warum zu wenig und sehr viel Wasser die Keimung im Modell begrenzen können. Protokolliere analoge Register-/Seitenwahl und digitale Abfragen; entnimm Zahlen und Ablaufbeziehungen und formuliere eine begrenzte Antwort.','Research why too little and excessive water can limit germination in the model. Record analog index/page selection and digital queries; extract counts and flow relationships and formulate a limited answer.'),pair('Ich suche Keimung Wasseraufnahme Sauerstoff und germination flooding oxygen, schlage analog B1Register/Seiten4–5 nach und wähle digital E1/E2. Trocken fehlt ausreichende Wasseraufnahme; überflutet kann Sauerstoff fehlen. Die18/2/5 Keimungen passen zum Modell, beweisen aber keine allgemeine Artregel. B2 kann die Wasserfrage nicht beantworten; E3 behauptet eine allgemeine Lichtpflicht ohne Belege. Für weitere Arten brauche ich artspezifische Keimbedingungen und kontrollierte Vergleiche.','I search germination water uptake oxygen and germination flooding oxygen, consult analog B1index/pages4–5 and select digital E1/E2. Dry conditions limit water uptake; flooding can limit oxygen. The18/2/5 counts fit the model but prove no universal species rule. B2 cannot answer the water question; E3 asserts universal light need without evidence. Further species need species-specific conditions and controlled comparisons.'),pair('Der neue Auftrag betrifft Lichtkeimer. Welche bisherige Quelle genügt nicht und wie müsste die Recherche enger werden?','The new task concerns seeds requiring light. Which prior source is insufficient and how should research narrow?'),pair('Die reine Wasser-/Sauerstofftabelle genügt nicht. Ich suche Artname Lichtkeimung Vergleich Hell Dunkel und ergänze ein analoges artspezifisches Register sowie digitale kontrollierte Lichtvergleiche.','The water/oxygen table is insufficient. I search species name light germination light dark comparison and add an analog species-specific index plus digital controlled light comparisons.'),[pair('Analoger und digitaler tatsächlicher Rechercheweg statt bloßer fertiger Antwort.','Actual analog/digital research route rather than only a ready answer.'),pair('Zahlen und Prozessmodell werden korrekt zusammengeführt.','Counts and process model are correctly combined.'),pair('Keine unzulässige Verallgemeinerung; Suchstrategie im Transfer erweitert.','No unjustified generalization; search strategy extended in transfer.')])],['Cases are controlled own media simulations, not claims of completed external research or actual learners. Native independent D/P and original-source checks remain pending.'])

goal('data',[
 (pair('Herkunft, Erhebungsweise, Aktualitätskontext und Darstellungswahl bestimmen die Aussagekraft.','Origin, data collection, temporal context and presentation choice determine evidential force.'),pair('Prüfe Autor-/Trägerrolle, Nachweis-/Methodenlage und relevante Darstellungsentscheidungen konkret.','Check author/publisher role, evidence/methods and relevant presentation decisions concretely.')),
 (pair('Autorintention kann Auswahl und Rahmung beeinflussen, macht eine Aussage aber weder automatisch falsch noch wahr.','Author intention can affect selection and framing without automatically making a claim false or true.'),pair('Verknüpfe belegte Intention/Interessen mit einer konkreten Auslassung oder Rahmung, ohne Gesinnung als Wahrheitsbeweis zu verwenden.','Connect documented intention/interests to a concrete omission or framing without treating intention as proof of truth.')),
 (pair('Quellenabgleich vergleicht dieselbe Größe und denselben Kontext und lässt echten Dissent oder Unsicherheit stehen.','Cross-source comparison uses the same quantity and context and preserves genuine disagreement or uncertainty.'),pair('Vergleiche Aussagen fair, erkläre scheinbare Widersprüche und formuliere eine begrenzt belastbare Schlussfolgerung.','Compare claims fairly, explain apparent contradictions and formulate a limited supportable conclusion.'))], [
 case('source-quality-algae','Algenmittel im Modell',pair('Q1 fiktive Herstellerkarte: reduziert Algen um80%, Balken nur behandelte Aquarien, n=5, Licht gesenkt; Ziel Produktverkauf. Q2 fiktives unabhängiges Klassenlabor: unbehandelt bei konstantem Licht20Flächeneinheiten Algen, behandelt16, je10Aquarien; Wasserbedingungen kontrolliert; Ziel reproduzierbarer Vergleich. Q3 fiktive Fachübersicht erklärt: Licht und Nährstoffe beeinflussen Wachstum; einzelne Modellzahlen sind nicht auf Freilandgewässer übertragbar.','Q1 fictitious manufacturer card: reduces algae by80%, bars only treated tanks, n=5, light reduced; purpose product sales. Q2 fictitious independent school laboratory: untreated at constant light20areaunits algae, treated16,10tanks each; water conditions controlled; purpose reproducible comparison. Q3 fictitious technical overview: light and nutrients affect growth; individual model numbers do not transfer to open waters.'),pair('Analysiere Qualität, Herkunft, Vertrauenswürdigkeit, Diagrammwahl und Intention. Gleiche80% mit20→16 ab. Was darf als Produktwirkung behauptet werden?','Analyze quality, origin, trustworthiness, chart choice and intention. Compare80% with20→16. What may be claimed as a product effect?'),pair('Q1 trennt Mittel und Lichtänderung nicht; die fehlende Kontrolle und einseitige Balkenwahl begünstigen die Verkaufsbehauptung. Das beweist keine Täuschung, begrenzt aber die Kausalzuordnung. Q2 zeigt4/20=20% Unterschied unter kontrolliertem Licht im gegebenen Modell; Stichprobe und Replikation bleiben begrenzt. Q1/Q2 messen unterschiedliche Bedingungen, also keinen sauberen80-versus20-Widerspruch. Q3 liefert die biologische Gegenhypothese und Transfergrenze. Belastbar ist der begrenzte Q2-Vergleich, keine universelle Freilandwirkung.','Q1 does not separate treatment from changed light; lack of control and one-sided bars favor the sales claim. This does not prove deception but limits causal attribution. Q2 shows4/20=20% difference under controlled light in this model; sample and replication remain limited. Q1/Q2 use different conditions, so there is no clean80-versus20 contradiction. Q3 supplies the biological alternative and transfer limit. The limited Q2 comparison is supportable, not a universal open-water effect.'),pair('Q2 wird künftig vom Hersteller finanziert, Methoden und Daten bleiben offen. Muss die Quelle verworfen werden?','Q2 is subsequently funded by the manufacturer while methods/data remain open. Must it be rejected?'),pair('Nein; Finanzierung ist relevant und offen zu benennen. Ich prüfe Kontrolle, Datenvollständigkeit und unabhängige Wiederholung weiter; nicht automatisch falsche Ergebnisse.','No; funding is relevant and should be disclosed. I continue checking controls, completeness and independent replication; results are not automatically false.'),[pair('Konkrete Herkunft-/Methoden-/Darstellungskritik.','Concrete origin/method/presentation critique.'),pair('Intention ohne ad-hominem-Schluss, Zahlenkontexte korrekt abgeglichen.','Intention without ad-hominem inference; numeric contexts correctly compared.'),pair('Begrenzte Schlussfolgerung und differenzierte Finanzierungsvariation.','Limited conclusion and nuanced funding variation.')]),
 case('source-quality-birds','Nistkästen und Vogelzahlen',pair('R1 fiktive Naturschutzbroschüre: Doppelt so viele Brutpaare nach Nistkästen, Vorher10/Nachher20 in einem Park; warme Frühjahrssaison, kein Vergleichspark; Ziel Spenden. R2 fiktiver Kommunalbericht: Beobachtete Brutpaare pro drei Parks, mit Kästen20/18/16, ohne18/17/15; standardisierte Begehung, Baumhöhlen nicht gezählt; Ziel Bestandsplanung. R3 Modellkurve beginnt bei14 statt0 und verstärkt optisch Unterschiede von1–2.','R1 fictitious conservation leaflet: Twice as many breeding pairs after nest boxes, before10/after20 in one park; warm spring, no control park; purpose donations. R2 fictitious municipal report: breeding pairs in three parks, with boxes20/18/16, without18/17/15; standardized visits, tree cavities not counted; purpose population planning. R3 model chart starts at14 rather than0 and visually amplifies differences of1–2.'),pair('Vergleiche Datenbasis und Medienrahmung. Welche Gemeinsamkeiten, Unterschiede und ungeklärten Einflüsse erklären die Aussagen?','Compare data basis and media framing. What similarities, differences and unresolved influences explain the claims?'),pair('R1 hat einen echten Modellanstieg10→20, aber keine Trennung von Nistkästen, Wetter und anderen Änderungen. Die Spendenintention erklärt die positive Rahmung, nicht automatisch Unwahrheit. R2 zeigt kleine Unterschiede mit anderer Erhebung und unkontrollierten Höhlen; ebenfalls keine eindeutige Ursache. R3 darf nicht als Verdopplung gelesen werden: Achsengrenze und tatsächliche Werte sind auszuweisen. Quellen teilen Hinweise auf Nutzung, tragen aber verschiedene Aussagen. Ich fordere kontrollierte Zeit-/Parkvergleiche und Höhlendaten, statt eine Quelle allein nach ihrem Träger zu wählen.','R1 contains a real modeled increase10→20 but does not separate boxes, weather and other changes. Donation purpose explains positive framing, not automatic falsehood. R2 shows small differences under another survey with uncontrolled cavities; also no unique cause. R3 must not be read as doubling: axis bounds and actual values should be stated. Sources suggest use but support different claims. I request controlled time/park comparisons and cavity data instead of selecting by publisher alone.'),pair('R2 zählt nun Belegung einzelner Kästen statt alle Brutpaare. Kann diese Zahl den Parkbestand direkt ersetzen?','R2 now counts occupied boxes rather than all breeding pairs. Can this directly replace park population counts?'),pair('Nein; die Zielgröße ist geändert. Kastenbelegung erfasst keine Bruten in natürlichen Höhlen und darf nur getrennt verglichen werden.','No; the outcome changed. Box occupancy omits nests in natural cavities and requires separate comparison.'),[pair('Verschiedene Erhebungsgrößen und Kontrolle identifiziert.','Different outcomes and controls identified.'),pair('Trägerintention und graphische Rahmung konkret verbunden.','Publisher intention and graphical framing concretely connected.'),pair('Kausal-/Transfergrenzen und neuer Größenwechsel korrekt.','Causal/transfer limits and new outcome change correctly handled.')])],['Trustworthiness is tied to actual evidence and transparency, not an official/private publisher binary or a required preferred standpoint.'])

goal('representation',[
 (pair('Strukturierung ordnet biologische Informationen nach begründeten Beziehungen und behält relevante Bedingungen.','Structuring organizes biological information by justified relationships and retains relevant conditions.'),pair('Ordne Material in eine begründete Tabelle, Ablauf- oder Beziehungsstruktur und kennzeichne Variablen/Bedingungen.','Organize material into a justified table, flow or relationship structure and label variables/conditions.')),
 (pair('Ein Darstellungswechsel bewahrt Werte, Einheiten, Richtung und Bedeutung.','A change of representation preserves values, units, direction and meaning.'),pair('Überführe die Informationen in eine geeignete zweite Darstellung und begründe Achsen, Beschriftungen oder Pfeile.','Transform information into a suitable second representation and justify axes, labels or arrows.')),
 (pair('Interpretation und Schlussfolgerung bleiben von Beobachtung und unbelegter Ursache unterscheidbar.','Interpretation and conclusion remain distinct from observations and unsupported causes.'),pair('Leite eine fachlich passende Schlussfolgerung ab und markiere eine Grenze oder Gegeninterpretation.','Derive a biologically suitable conclusion and mark a limit or alternative interpretation.'))], [
 case('representation-seed','Keimverlauf als Tabelle und Kurve',pair('Ein eigenes Keimmodell verfolgt dieselben20Samen an Tagen0,2,4,6: kumulativ gekeimt0,4,14,18; Temperatur20°C, gleich feuchtes Substrat. Notizen: Tag4 zehn neue Keimungen; Tag6 vier neue Keimungen. Keine weitere Samenart wurde untersucht.','An authored germination model follows the same20seeds at days0,2,4,6: cumulative germination0,4,14,18;20°C, equally moist substrate. Notes: day4 ten new germinations; day6 four new germinations. No other species was examined.'),pair('Strukturiere Notizen und Messwerte, überführe sie in ein beschriftetes Liniendiagramm und interpretiere Verlauf und Schlussgrenze. Unterscheide kumulativ von neu gekeimt.','Structure notes/measurements, transform them into a labeled line chart and interpret trend and limits. Distinguish cumulative from newly germinated.'),pair('Die Tabelle enthält Tag, kumulative Zahl und neue Zahl seit der vorigen Messung:0/0/0;2/4/4;4/14/10;6/18/4. X ist Zeit in Tagen, Y kumulativ gekeimte Samen0–20; die Punkte0,4,14,18 steigen und dürfen nicht als Tagesraten beschriftet werden. Im Modell liegt der größte beobachtete Zuwachs zwischen Tag2 und4;18/20=90% bis Tag6. Das belegt weder spätere Endkeimung noch ein Optimum20°C oder andere Arten.','The table contains day, cumulative count and new count since prior measurement:0/0/0;2/4/4;4/14/10;6/18/4. X is time in days, Y cumulative germinated seeds0–20; points0,4,14,18 rise and must not be labeled daily rates. Greatest observed increase is between days2 and4;18/20=90% by day6. This establishes neither final germination later, a20°C optimum nor other species.'),pair('Eine zweite Serie umfasst40Samen mit24Keimungen an Tag6. Wie vergleichst du fair?','A second series has40seeds with24germinations at day6. How do you compare fairly?'),pair('Ich stelle beide als Anteil dar:90% versus60%, bei benannten Bedingungen.24 ist absolut mehr, aber relativ weniger; ohne kontrollierte Bedingungen keine Ursache.','I show proportions:90% versus60%, with conditions stated.24 is greater absolutely but lower relatively; no cause follows without controls.'),[pair('Alle Daten und Bedingungen korrekt strukturiert.','All data and conditions correctly structured.'),pair('Kumulativ/Raten, Achsen und Einheiten stimmen im Wechsel.','Cumulative/rate distinction, axes and units survive transformation.'),pair('Begrenzte Deutung und fairer Nennerwechsel.','Limited interpretation and fair denominator change.')]),
 case('representation-stream','Nährstoffe und Sauerstoff im Bachmodell',pair('Drei Modellmesspunkte: vor Einleitung Nitrat2mg/L, Sauerstoff8mg/L; direktnach Nitrat8, Sauerstoff7;1kmweiter Nitrat6, Sauerstoff4. Zusatznotiz: Algenbildung kann nach Nährstoffzufuhr steigen; mikrobieller Abbau organischer Stoffe verbraucht Sauerstoff. Messungen stammen aus einer Begehung, Fließtempo/Temperatur fehlen.','Three modeled locations: upstream nitrate2mg/L, oxygen8mg/L; immediatelyafter nitrate8, oxygen7;1kmdownstream nitrate6, oxygen4. Note: nutrient input can increase algal growth; microbial organic-matter breakdown uses oxygen. One survey only; flow rate/temperature unavailable.'),pair('Ordne Messung, Prozessannahme und offene Faktoren. Überführe den Text in eine Werteübersicht und ein begrenztes Prozessdiagramm; interpretiere ohne Messreihenfolge mit Ursache zu verwechseln.','Organize measurements, process assumption and missing factors. Transform text into a values table and limited process diagram; interpret without confusing measurement order with causation.'),pair('Die Tabelle bewahrt Ort und mg/L für beide Größen. Ein Prozessdiagramm darf Nährstoffzufuhr→möglichesAlgenwachstum→organischerAbbau→Sauerstoffverbrauch als gekennzeichnete Hypothese zeigen; die drei Werte sind Beobachtungsknoten. Nitrat steigt zunächst, Sauerstoff sinkt stromab. Die Einzelbegehung prüft die gesamte Kette nicht und misst weder Algen noch Abbaurate; Temperatur und Zuflüsse bleiben Alternativen. Zwei Größen auf einer unbeschrifteten gemeinsamen Achse oder ein Pfeil Nitrat ist Sauerstoff wären falsch.','The table preserves location and mg/L for both measures. A process diagram may show nutrientinput→possiblealgalgrowth→organicbreakdown→oxygenuse as a labeled hypothesis; the three values are observation nodes. Nitrate initially rises while oxygen falls downstream. A single survey does not test the whole chain or measure algae/decay; temperature and tributaries remain alternatives. Two quantities on an unlabeled common axis or nitrate is oxygen arrow would be wrong.'),pair('Nach Regen ist der Sauerstoff am dritten Punkt wieder8mg/L. Muss die vorherige Abbauhypothese sicher falsch sein?','After rain oxygen at the third point is8mg/L again. Must the prior breakdown hypothesis be false?'),pair('Nein; veränderte Durchmischung, Temperatur oder Zufluss können den Wert verändern. Ich ergänze die neue Zeitbedingung und kennzeichne die Hypothese weiterhin als prüfbedürftig.','No; mixing, temperature or inflow can change oxygen. I add the new temporal condition and retain the hypothesis as requiring testing.'),[pair('Messwerte, Einheiten und hypothetische Prozesse getrennt.','Measurements, units and hypothetical processes separated.'),pair('Zwei geeignete Darstellungsformen ohne Bedeutungsverlust.','Two suitable representations without loss of meaning.'),pair('Keine kausale Überdehnung; frische Gegenbeobachtung eingeordnet.','No causal overreach; fresh contrary observation interpreted.')])],['The goal concerns structuring/interpreting/re-expressing supplied information, not conducting a new experiment or deriving quantitative kinetic laws.'])

goal('concept',[
 (pair('Alltagssprache wird in fachlich präzise Aussagen überführt; Funktion und bewirkender Mechanismus sind verschiedene Fragen.','Everyday wording is translated into precise biological claims; function and producing mechanism answer different questions.'),pair('Kennzeichne einen alltagssprachlichen Ausdruck, formuliere ihn fachsprachlich und unterscheide Funktionsbeschreibung von Ursache.','Identify an everyday expression, reformulate it technically and distinguish function from cause.')),
 (pair('Proximate Erklärung betrifft aktuelle Mechanismen/Entwicklung; ultimate Erklärung betrifft evolutionäre Entstehung bzw. reproduktive Folgen über Generationen.','Proximate explanation concerns current mechanisms/development; ultimate explanation concerns evolutionary origin or reproductive consequences across generations.'),pair('Gib für dasselbe Phänomen jeweils einen schlüssigen proximaten und ultimaten Zusammenhang aus dem Material an.','Provide a coherent proximate and ultimate relationship from the material for the same phenomenon.')),
 (pair('Evolution und Regulation handeln nicht mit vorausgesehenen Zwecken; Nutzen allein erklärt weder Entstehung noch Mechanismus.','Evolution and regulation do not act with foreseen purposes; usefulness alone explains neither origin nor mechanism.'),pair('Korrigiere eine finale Begründung und kennzeichne den Evidenz-/Hypothesenstatus der alternativen Erklärung.','Correct a teleological explanation and label the evidence/hypothesis status of the alternative.'))], [
 case('language-light-response','Lichtreaktion im Pflanzenmodell',pair('Im eigenen Pflanzenmodell aktiviert seitliches Licht einen Rezeptor; ein Signal verändert ungleiches Zellstrecken, der Spross krümmt sich zum Licht. In einer modellierten Population sind Unterschiede der Lichtreaktion vererbbar; Varianten mit mehr verwertbarem Licht hinterlassen unter diesen Bedingungen mehr Nachkommen. Das ist ein vorgegebenes Modell, kein erhobener Evolutionsnachweis. Alltagssatz: Die Pflanze weiß, wo die Sonne ist, und wächst dorthin, damit sie später mehr Kinder bekommt.','In an authored plant model side light activates a receptor; signaling changes unequal cell elongation and the shoot bends toward light. In a modeled population variation in light response is heritable; variants with more usable light leave more offspring under these conditions. This is a supplied model, not observed evolutionary proof. Everyday sentence: The plant knows where the sun is and grows there so it will later have more children.'),pair('Differenziere Alltags-/Fachsprache, Funktion/Mechanismus sowie proximat/ultimat. Ersetze die finale Begründung durch eine materialgebundene Erklärung.','Differentiate everyday/technical language, function/mechanism and proximate/ultimate. Replace teleology with an explanation bound to the material.'),pair('Weiß und Kinder sind anthropomorphe Alltagssprache; fachlich reagieren Rezeptoren/Signalwege, Nachkommen werden gebildet. Proximat: seitlicher Reiz→Signal→ungleiche Streckung→Krümmung. Funktion: bessere Lichtausnutzung kann Photosynthese unterstützen; das ist nicht der unmittelbare Mechanismus. Ultimat im Modell: vererbbare Reaktionsvarianten unterscheiden sich im Fortpflanzungserfolg und werden über Generationen unterschiedlich häufig. Die Pflanze plant keine Nachkommen und erzeugt die Variante nicht aus Bedürfnis. Eine echte historische Erklärung bräuchte weitere Evidenz; der Modellnutzen allein beweist sie nicht.','Knows and children are anthropomorphic everyday wording; technically receptors/signals respond and offspring are produced. Proximate: directional stimulus→signal→unequal elongation→bending. Function: improved light use can support photosynthesis; that is not the immediate mechanism. Ultimate in the model: inherited response variants differ in reproductive success and change frequency across generations. The plant plans no offspring and does not create variation from need. A real historical explanation needs further evidence; modeled usefulness alone does not prove it.'),pair('In einem Versuch wird der Rezeptor blockiert und die Krümmung verschwindet. Beweist das bereits die Evolutionsgeschichte?','In a trial the receptor is blocked and bending disappears. Does that prove evolutionary history?'),pair('Nein; es stützt einen aktuellen Mechanismus im gegebenen Versuch, nicht die historische Entstehung oder Vererbung/Selektionsfolge über Generationen.','No; it supports a current mechanism in that trial, not historical origin or inherited selection across generations.'),[pair('Alltag/Fach und Funktion/Mechanismus korrekt differenziert.','Everyday/technical and function/mechanism correctly differentiated.'),pair('Beide Erklärungsebenen für dasselbe Phänomen konkret.','Both explanatory levels concretely address the same phenomenon.'),pair('Finalität entfernt, Hypothesenstatus und frischer Ebenenwechsel korrekt.','Teleology removed, hypothesis status and fresh level distinction correct.')]),
 case('language-moth-color','Färbung und Selektion im Insektenmodell',pair('Modellmaterial: Ein geerbter Unterschied in Pigmentbildung bewirkt helle oder dunkle Flügel. Auf dunklem Hintergrund werden helle Individuen häufiger gefressen; dunkle hinterlassen dort mehr Nachkommen. Auf hellem Hintergrund kehrt sich dieser Unterschied um. Schülersatz: Die Falter wurden dunkel, um sich vor Feinden zu verstecken; das schützt sie und erklärt alles.','Model material: an inherited difference in pigment production causes light/dark wings. On dark background light individuals are eaten more often; dark individuals leave more offspring. On light background the difference reverses. Student sentence: The moths became dark in order to hide from predators; that protects them and explains everything.'),pair('Erläutere fachsprachlich proximaten Mechanismus, mögliche Funktion und ultimate Erklärung. Korrigiere finale Sprache und begrenze die Aussage auf den Modellkontext.','Explain the proximate mechanism, possible function and ultimate explanation in technical language. Correct teleological wording and limit the claim to the model context.'),pair('Proximat bewirkt der geerbte Pigmentbildungsunterschied verschiedene Flügelpigmentierung. Funktional kann geringe Auffälligkeit auf passendem Hintergrund Fressrisiko senken. Ultimat unterscheiden sich bestehende vererbbare Varianten in Überleben und Zahl der Nachkommen; so verschieben sich Häufigkeiten, ohne zielgerichtete Farbentscheidung. Schutzfunktion allein sagt nichts über Pigmentchemie oder tatsächliche Geschichte. Auf hellem Hintergrund ist dunkel nicht allgemein besser; Anpassung ist kontextabhängig.','Proximately, inherited pigment-production differences cause different wing pigmentation. Functionally, low contrast against a matching background can lower predation risk. Ultimately, existing inherited variants differ in survival and offspring number, changing frequencies without a purposeful color decision. Protective function alone explains neither pigment chemistry nor actual history. Dark is not universally better on light background; adaptation depends on context.'),pair('Ein Individuum verdunkelt sich durch äußere Verschmutzung, ohne Änderung vererbbarer Pigmentbildung. Ist das dieselbe ultimate Erklärung?','An individual darkens through surface dirt without changing inherited pigment production. Is the same ultimate explanation sufficient?'),pair('Nein; der unmittelbare Farbwechsel ist ein anderer proximate Vorgang. Für evolutionäre Häufigkeitsänderung müsste der relevante Unterschied vererbbar sein; Verschmutzung allein liefert das nicht.','No; the immediate color change has another proximate cause. Evolutionary frequency change requires relevant inherited variation; dirt alone does not provide it.'),[pair('Präzise Fachsprache und nicht gleichgesetzte Erklärungsebenen.','Precise terminology and distinct explanatory levels.'),pair('Variation/Vererbung/Fortpflanzung ohne Bedürfnis- oder Zweckursache.','Variation/inheritance/reproduction without need or purpose as cause.'),pair('Kontextabhängigkeit und nichtvererbbaren Gegenfall erklären.','Explain context dependence and noninherited countercase.')])],['No claim that all listed illustrative mechanisms are required memorized named pathways; all biological premises are supplied. Independent semantic atomicity remains valid and unchanged; fresh native text review pending.'])
